#include "static_drift_compensator.h"
#include <inttypes.h>
#include <stdio.h>
int main(void){StaticDriftConfig cfg;StaticDriftCompensator c;StaticDriftInput i;StaticDriftOutput o;unsigned cal,over,fault,rail;StaticDriftCompensator_DefaultConfig(&cfg);if(!StaticDriftCompensator_Init(&c,&cfg))return 2;puts("timestamp_ms,sample_sequence,corrected_mass_ug,drift_offset_ug,reference_mass_ug,state,freeze_reason,update_count,freeze_count,total_positive_correction_ug,total_negative_correction_ug");while(scanf("%"SCNu32",%"SCNu32",%"SCNd64",%u,%u,%u,%u",&i.timestamp_ms,&i.sample_sequence,&i.measured_mass_ug,&cal,&over,&fault,&rail)==7){i.calibration_valid=cal!=0;i.overload=over!=0;i.fault_active=fault!=0;i.near_rail=rail!=0;if(!c.enabled)StaticDriftCompensator_Enable(&c,i.measured_mass_ug,i.timestamp_ms);if(!StaticDriftCompensator_Process(&c,&i,&o))return 3;printf("%"PRIu32",%"PRIu32",%"PRId64",%"PRId64",%"PRId64",%u,%u,%"PRIu32",%"PRIu32",%"PRId64",%"PRId64"\n",i.timestamp_ms,i.sample_sequence,o.corrected_mass_ug,o.drift_offset_ug,o.reference_mass_ug,(unsigned)o.state,(unsigned)o.freeze_reason,o.update_count,o.freeze_count,o.total_positive_correction_ug,o.total_negative_correction_ug);}return ferror(stdin)?4:0;}
